CREATE TABLE public.prime99_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),reference text NOT NULL UNIQUE CHECK(reference ~ '^[A-Za-z0-9-]{6,64}$'),amount integer NOT NULL DEFAULT 99 CHECK(amount=99),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),submitted_at timestamptz NOT NULL DEFAULT now(),received_at timestamptz,ends_at timestamptz,reviewed_by uuid,review_note text NOT NULL DEFAULT '');
GRANT SELECT,INSERT ON public.prime99_payments TO authenticated; GRANT ALL ON public.prime99_payments TO service_role;
ALTER TABLE public.prime99_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY prime99_read ON public.prime99_payments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY prime99_submit ON public.prime99_payments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.account_allowed(auth.uid()) AND status='pending' AND received_at IS NULL AND ends_at IS NULL AND reviewed_by IS NULL AND review_note='');
CREATE FUNCTION public.has_prime99(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_allowed(_user) AND EXISTS(SELECT 1 FROM public.prime99_payments WHERE user_id=_user AND status='approved' AND received_at<=now() AND ends_at>now()) $$;
REVOKE ALL ON FUNCTION public.has_prime99(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_prime99(uuid) TO authenticated,service_role;
CREATE FUNCTION public.my_prime99() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('active',public.has_prime99(auth.uid()),'ends_at',(SELECT max(ends_at) FROM public.prime99_payments WHERE user_id=auth.uid() AND status='approved'),'amount',99) $$;
REVOKE ALL ON FUNCTION public.my_prime99() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_prime99() TO authenticated;
CREATE TABLE public.monthly_post_periods(user_id uuid PRIMARY KEY REFERENCES public.profiles(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL);
GRANT SELECT ON public.monthly_post_periods TO authenticated; GRANT ALL ON public.monthly_post_periods TO service_role;
ALTER TABLE public.monthly_post_periods ENABLE ROW LEVEL SECURITY;
CREATE POLICY post_period_owner ON public.monthly_post_periods FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.monthly_post_usage(post_id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.profiles(id),used_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.monthly_post_usage TO authenticated; GRANT ALL ON public.monthly_post_usage TO service_role;
ALTER TABLE public.monthly_post_usage ENABLE ROW LEVEL SECURITY;
CREATE POLICY post_usage_owner ON public.monthly_post_usage FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX monthly_post_usage_owner_time ON public.monthly_post_usage(user_id,used_at);
CREATE FUNCTION public.guard_monthly_three_posts() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE anchor public.monthly_post_periods; used integer; BEGIN PERFORM 1 FROM public.profiles WHERE id=NEW.user_id FOR UPDATE; SELECT * INTO anchor FROM public.monthly_post_periods WHERE user_id=NEW.user_id; IF anchor.user_id IS NULL OR anchor.ends_at<=now() THEN INSERT INTO public.monthly_post_periods(user_id,starts_at,ends_at) VALUES(NEW.user_id,now(),now()+interval '1 month') ON CONFLICT(user_id) DO UPDATE SET starts_at=excluded.starts_at,ends_at=excluded.ends_at RETURNING * INTO anchor; END IF; SELECT count(*) INTO used FROM public.monthly_post_usage WHERE user_id=NEW.user_id AND used_at>=anchor.starts_at AND used_at<anchor.ends_at; IF used>=3 THEN RAISE EXCEPTION 'MONTHLY_THREE_POST_LIMIT'; END IF; INSERT INTO public.monthly_post_usage(post_id,user_id) VALUES(NEW.id,NEW.user_id); RETURN NEW; END $$;
CREATE TRIGGER z_monthly_three_posts BEFORE INSERT ON public.posts FOR EACH ROW EXECUTE FUNCTION public.guard_monthly_three_posts();
CREATE FUNCTION public.my_post_quota99() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('limit',3,'used',(SELECT count(*) FROM public.monthly_post_usage WHERE user_id=auth.uid() AND used_at>=coalesce(p.starts_at,now()) AND used_at<p.ends_at),'ends_at',p.ends_at) FROM (SELECT starts_at,ends_at FROM public.monthly_post_periods WHERE user_id=auth.uid() AND ends_at>now() UNION ALL SELECT now(),NULL::timestamptz WHERE NOT EXISTS(SELECT 1 FROM public.monthly_post_periods WHERE user_id=auth.uid() AND ends_at>now())) p LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.my_post_quota99() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.my_post_quota99() TO authenticated;
CREATE OR REPLACE FUNCTION public.can_notify(_uid uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE pref public.notification_preferences; zone text; local_now timestamp; used integer; cap integer; BEGIN IF _uid IS NULL OR NOT public.has_prime99(_uid) THEN RETURN false; END IF; SELECT * INTO pref FROM public.notification_preferences WHERE user_id=_uid; zone:=coalesce(pref.timezone,'Asia/Kolkata'); local_now:=now() AT TIME ZONE zone; IF pref.enabled=false THEN RETURN false; END IF; IF pref.quiet_start IS NOT NULL AND ((pref.quiet_start<pref.quiet_end AND local_now::time>=pref.quiet_start AND local_now::time<pref.quiet_end) OR (pref.quiet_start>pref.quiet_end AND (local_now::time>=pref.quiet_start OR local_now::time<pref.quiet_end))) THEN RETURN false; END IF; cap:=least(coalesce(pref.daily_limit,5),5); SELECT count(*) INTO used FROM public.notifications WHERE user_id=_uid AND created_at>=date_trunc('day',local_now) AT TIME ZONE zone; RETURN used<cap; END $$;
CREATE FUNCTION public.guard_prime99_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_notify(NEW.user_id) THEN RETURN NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER a_prime99_notice BEFORE INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.guard_prime99_notice();
CREATE POLICY prime99_notifications_read ON public.notifications AS RESTRICTIVE FOR SELECT TO authenticated USING(public.has_prime99(auth.uid()));
CREATE OR REPLACE FUNCTION public.confirm_referral_cash(_user uuid,_reference text,_amount_paise bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE receipt uuid; ref uuid; prize bigint; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; IF _amount_paise<=0 OR _amount_paise>100000000000 OR length(trim(_reference))<3 OR length(trim(_reference))>120 THEN RAISE EXCEPTION 'INVALID_RECEIPT'; END IF; INSERT INTO public.referral_cash_receipts(user_id,reference,amount_paise,confirmed_by) VALUES(_user,trim(_reference),_amount_paise,auth.uid()) RETURNING id INTO receipt; SELECT referrer_id INTO ref FROM public.referral_vip_joins WHERE joined_user=_user; IF ref IS NOT NULL AND public.has_prime99(ref) THEN prize:=(_amount_paise*20)/100; IF prize>0 THEN INSERT INTO public.referral_cash_rewards(receipt_id,user_id,amount_paise) VALUES(receipt,ref,prize); IF public.can_notify(ref) THEN INSERT INTO public.notifications(user_id,message) VALUES(ref,'వేడుక రోజు ఇచ్చేందుకు మీ పరిచయ చెల్లింపుపై 20% బహుమతి ₹'||(prize::numeric/100)||' లెక్కలో నమోదైంది; ఇంకా నగదు ఇవ్వలేదు.'); END IF; END IF; END IF; RETURN receipt; END $$;
COMMENT ON TABLE public.referral_invitee_rewards IS 'Historical invitee reward ledger preserved. New receipts award only eligible direct inviter; no new invitee rewards.';
CREATE FUNCTION public.review_prime99(_id uuid,_approve boolean,_note text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.prime99_payments; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT * INTO p FROM public.prime99_payments WHERE id=_id FOR UPDATE; IF p.id IS NULL OR p.status<>'pending' THEN RAISE EXCEPTION 'NO_PENDING_PAYMENT'; END IF; PERFORM 1 FROM public.profiles WHERE id=p.user_id FOR UPDATE; UPDATE public.prime99_payments SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,received_at=CASE WHEN _approve THEN now() ELSE NULL END,ends_at=CASE WHEN _approve THEN now()+interval '1 month' ELSE NULL END,reviewed_by=auth.uid(),review_note=left(coalesce(_note,''),500) WHERE id=_id; IF _approve THEN INSERT INTO public.monthly_post_periods(user_id,starts_at,ends_at) VALUES(p.user_id,now(),now()+interval '1 month') ON CONFLICT(user_id) DO UPDATE SET starts_at=excluded.starts_at,ends_at=excluded.ends_at; PERFORM public.confirm_referral_cash(p.user_id,p.reference,9900); END IF; END $$;
REVOKE ALL ON FUNCTION public.review_prime99(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_prime99(uuid,boolean,text) TO authenticated;
CREATE TABLE public.referral_prize_payouts(receipt_id uuid PRIMARY KEY REFERENCES public.referral_cash_rewards(receipt_id),paid_at timestamptz NOT NULL DEFAULT now(),reference text NOT NULL,recorded_by uuid NOT NULL);
GRANT SELECT ON public.referral_prize_payouts TO authenticated; GRANT ALL ON public.referral_prize_payouts TO service_role;
ALTER TABLE public.referral_prize_payouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY payout_read ON public.referral_prize_payouts FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.referral_cash_rewards r WHERE r.receipt_id=referral_prize_payouts.receipt_id AND r.user_id=auth.uid()));
CREATE FUNCTION public.record_referral_prize_paid(_receipt uuid,_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; IF length(trim(_reference))<6 OR length(_reference)>120 THEN RAISE EXCEPTION 'INVALID_REFERENCE'; END IF; INSERT INTO public.referral_prize_payouts(receipt_id,reference,recorded_by) VALUES(_receipt,trim(_reference),auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.record_referral_prize_paid(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_referral_prize_paid(uuid,text) TO authenticated;
ALTER TABLE public.referral_board_consent ADD COLUMN photo_consent boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.public_referral_vip_board() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH configuration AS (SELECT CASE WHEN now()<coalesce((SELECT started_at FROM public.referral_vip_campaign WHERE id),now())+interval '15 days' THEN 10 WHEN now()<coalesce((SELECT started_at FROM public.referral_vip_campaign WHERE id),now())+interval '30 days' THEN 25 ELSE 50 END AS places), ranked AS (SELECT r.user_id,r.joins,row_number() OVER(ORDER BY r.joins DESC,r.rank_no) AS place,c.display_name,c.published,c.region,c.photo_consent FROM public.referral_vip_ranks() r JOIN public.referral_board_consent c ON c.user_id=r.user_id WHERE c.region IN('AP','TG')) SELECT jsonb_build_object('limit',(SELECT places FROM configuration),'event_label',coalesce((SELECT event_label FROM public.referral_vip_campaign WHERE id),'డిసెంబర్ 31'),'totals',jsonb_build_object('TG',(SELECT count(*) FROM public.referral_vip_joins j JOIN public.referral_board_consent c ON c.user_id=j.joined_user WHERE c.region='TG'),'AP',(SELECT count(*) FROM public.referral_vip_joins j JOIN public.referral_board_consent c ON c.user_id=j.joined_user WHERE c.region='AP')),'rows',coalesce((SELECT jsonb_agg(jsonb_build_object('rank',r.place,'count',r.joins,'name',CASE WHEN r.published THEN r.display_name ELSE '' END,'region',r.region,'photo_path',CASE WHEN r.photo_consent AND s.published AND s.photo_path LIKE s.user_id::text||'/%' THEN s.photo_path ELSE '' END) ORDER BY r.place) FROM ranked r LEFT JOIN public.service_profiles s ON s.user_id=r.user_id WHERE r.place<=(SELECT places FROM configuration)),'[]'::jsonb)) $$;
CREATE TABLE public.daily_referral_board_notices(user_id uuid NOT NULL REFERENCES public.profiles(id),day date NOT NULL,notification_id uuid REFERENCES public.notifications(id),PRIMARY KEY(user_id,day));
GRANT SELECT ON public.daily_referral_board_notices TO authenticated; GRANT ALL ON public.daily_referral_board_notices TO service_role;
ALTER TABLE public.daily_referral_board_notices ENABLE ROW LEVEL SECURITY;
CREATE POLICY daily_board_owner ON public.daily_referral_board_notices FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.dispatch_daily_referral_board() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE person record; notice uuid; board jsonb; today date:=(now() AT TIME ZONE 'Asia/Kolkata')::date; n integer:=0; leader text; BEGIN board:=public.public_referral_vip_board(); leader:=coalesce(board->'rows'->0->>'name',''); FOR person IN SELECT p.id FROM public.profiles p WHERE public.has_prime99(p.id) AND NOT EXISTS(SELECT 1 FROM public.daily_referral_board_notices d WHERE d.user_id=p.id AND d.day=today) ORDER BY p.id LIMIT 200 LOOP PERFORM 1 FROM public.profiles WHERE id=person.id FOR UPDATE; IF public.can_notify(person.id) THEN INSERT INTO public.daily_referral_board_notices(user_id,day) VALUES(person.id,today) ON CONFLICT DO NOTHING; IF FOUND THEN notice:=NULL; INSERT INTO public.notifications(user_id,message) VALUES(person.id,'నేటి పరిచయ పోటీ: తెలంగాణ '||(board->'totals'->>'TG')||', ఆంధ్రప్రదేశ్ '||(board->'totals'->>'AP')||' చేరికలు. '||CASE WHEN leader<>'' THEN 'ముందున్న వ్యక్తి: '||leader||'. ' ELSE '' END||'అనుమతించిన చిత్రాలు, తాజా స్థానాలు ముఖపు పేజీలో చూడండి.') RETURNING id INTO notice; IF notice IS NOT NULL THEN UPDATE public.daily_referral_board_notices SET notification_id=notice WHERE user_id=person.id AND day=today; n:=n+1; END IF; END IF; END IF; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.dispatch_daily_referral_board() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.dispatch_daily_referral_board() TO service_role;